/**
 * relay Design System — MCP shared handlers (transport-agnostic).
 *
 *   The tool definitions, formatting, and dispatch logic live here so both
 *   transports reuse exactly the same behaviour:
 *     - src/mcp/server.mjs  → stdio (local, bundled to dist/mcp.mjs via esbuild)
 *     - src/mcp/worker.mjs  → Streamable HTTP on Cloudflare Workers (remote)
 *
 *   Data comes from dist/mcp-index.json (generated by scripts/build-mcp.mjs).
 *   Each transport's bundler (esbuild / wrangler) inlines this JSON import.
 *
 *   Tools:
 *     get_setup                — CSS 導入手順（UI 着手前に最初に呼ぶ）
 *     list_components          — every component with name / 和名 / summary / classes
 *     get_component(name)      — full spec: props, states, colors, usage, classes, snippet
 *     get_tokens(category?)    — colors / typography / spacing / radius / shadow
 *     get_design_principles    — non-negotiable rules + forbidden patterns (Top 10)
 *     list_assets              — brand assets (logo / illustrations) with直リンク URL
 *     search(query)            — fuzzy search across components / tokens / principles
 *     get_sprint_kit           — planner/generator/evaluator agents + sprint workflow + hardcode gate hook の配布
 *
 *   Prompts (Claude Code では /mcp__<server>__sprint スラッシュコマンドになる):
 *     sprint(task?)            — sprint kit のインストール → Workflow 実行を指示
 */

import index from "../../dist/mcp-index.json" with { type: "json" };

export { index };
export const SERVER_INFO = { name: "relay-design-system", version: index.version };
export const TOKEN_CATEGORIES = Object.keys(index.tokens); // colors, typography, spacing, radius, shadow

/**
 * Standing guidance returned in the `initialize` result. MCP clients load this
 * as system context at connect time, so — unlike a tool the agent must choose to
 * call — these rules stay in effect through a whole implementation session. This
 * targets the common failure mode where an agent connects, calls a tool once,
 * then drifts back to hardcoded values mid-build.
 */
